const CACHE_NAME="my-shop-v2",ASSETS_TO_CACHE=["/","/index.html","/bundle.web.js","/manifest.json","/icon-user.png","/service-worker.js"];self.addEventListener("install",e=>{self.skipWaiting(),e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(ASSETS_TO_CACHE)))}),self.addEventListener("activate",e=>{self.clients.claim(),e.waitUntil(caches.keys().then(e=>Promise.all(e.filter(e=>e!==CACHE_NAME).map(e=>caches.delete(e)))))}),self.addEventListener("fetch",e=>{"GET"===e.request.method&&e.respondWith(fetch(e.request).then(t=>{if(t&&t.ok){const s=t.clone();caches.open(CACHE_NAME).then(t=>t.put(e.request,s))}return t}).catch(()=>caches.match(e.request).then(e=>e||caches.match("/index.html"))))});